// Acepta "10.50", "10,50" e incluso "1.500,50" — decide cuál símbolo es el
// separador decimal según cuál aparece último en el texto.
function parseMoneyInput(str) {
  let s = String(str ?? "").trim();
  if (!s) return 0;
  const hasComma = s.includes(",");
  const hasDot = s.includes(".");
  if (hasComma && hasDot) {
    if (s.lastIndexOf(",") > s.lastIndexOf(".")) {
      s = s.replace(/\./g, "").replace(",", ".");
    } else {
      s = s.replace(/,/g, "");
    }
  } else if (hasComma) {
    s = s.replace(",", ".");
  }
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

const todayISO = () => new Date().toISOString().slice(0, 10);
const currentMonthKey = () => new Date().toISOString().slice(0, 7); // YYYY-MM
const MESES = ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio", "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"];
const monthLabel = (monthKey) => {
  const [y, m] = monthKey.split("-").map(Number);
  return `${MESES[m - 1]} ${y}`;
};
// Enumera todos los meses ("YYYY-MM") entre dos meses, en orden cronológico ascendente.
const monthsBetween = (startKey, endKey) => {
  const [sy, sm] = startKey.split("-").map(Number);
  const [ey, em] = endKey.split("-").map(Number);
  const startIdx = sy * 12 + (sm - 1);
  const endIdx = ey * 12 + (em - 1);
  const lo = Math.min(startIdx, endIdx);
  const hi = Math.max(startIdx, endIdx);
  const out = [];
  for (let idx = lo; idx <= hi; idx++) {
    const y = Math.floor(idx / 12);
    const m = (idx % 12) + 1;
    out.push(`${y}-${String(m).padStart(2, "0")}`);
  }
  return out;
};
const daysLeftInMonth = () => {
  const now = new Date();
  const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
  return lastDay - now.getDate();
};
// % del mes ya transcurrido — es en qué % deberían ir ventas/presupuesto si el
// ritmo fuera parejo todos los días del mes.
// % del mes ya transcurrido, contando solo días hábiles de lunes a sábado
// (los domingos no cuentan ni para el total del mes ni para lo transcurrido).
const monthProgressPct = () => {
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth();
  const lastDay = new Date(year, month + 1, 0).getDate();
  const today = now.getDate();

  let totalDiasHabiles = 0;
  let diasHabilesTranscurridos = 0;
  for (let d = 1; d <= lastDay; d++) {
    const esDomingo = new Date(year, month, d).getDay() === 0;
    if (!esDomingo) {
      totalDiasHabiles++;
      if (d <= today) diasHabilesTranscurridos++;
    }
  }
  return totalDiasHabiles > 0 ? (diasHabilesTranscurridos / totalDiasHabiles) * 100 : 0;
};

